import importlib.util,csv,numpy as np,sys,pymc as pm
src=open('model_loop/models/range_restricted_rule_concepts.py').read().replace('EPSILON = 0.1','EPSILON = %s'%sys.argv[1])
import types;m=types.ModuleType('m');exec(src,m.__dict__)
r=list(csv.DictReader(open('model_loop/responses.csv')))
obs=m.prepare_observed(r)
with m.model: pm.set_data(obs)
f=m.model.compile_fn(m.model['p_yes'],inputs=m.model.value_vars,on_unused_input='ignore')
y=obs['rating'];best=None
rng=np.random.default_rng(0)
for it in range(300):
    pt={'shares':rng.dirichlet([3,3,1]),'kind_weights':rng.dirichlet(np.ones(5)),'width_scale':np.exp(rng.uniform(1,5.5)),'decade_boost':rng.normal(0,1.5)}
    ip={}
    for v in m.model.free_RVs:
        t=m.model.rvs_to_transforms[v]; ip[m.model.rvs_to_values[v].name]=t.forward(pt[v.name]).eval() if t else pt[v.name]
    p=f(ip); ll=(y*np.log(p)+(1-y)*np.log(1-p)).sum()
    if best is None or ll>best[0]: best=(ll,pt,p.mean())
print(sys.argv[1],best)
EOF
